+(a&&!c?'[锁]':'');u=(a&&c?v?'http://my.jjwxc.net/onebook_vip':'http://www.jjwxc.net/onebook':'http://:')+(a&&c?'.php?novelid='+x.novelid+'&chapterid='+d:('0000'+y).slice(-5)+'-'+java.md5Encode16(n));v=a&&v?'💰':'';
